'use strict';

/**
 * 打包产物冒烟测试
 *
 * 用法（仓库根目录）：
 *   node cloud/scripts/test-bundle.js
 *
 * 目的：`cloud/scripts/sync.js` 把整个云函数打成**单文件 index.js** 上线
 *      （为了绕开 Windows CLI 的反斜杠打包缺陷）。打包器是自己写的，所以必须自证：
 *      同一批断言分别跑「源码」与「打包产物」，结果必须一致。
 *
 * ⚠️ 这里只做**冒烟**，不做全量：全量用例（test-user-*）依赖直接 require 源模块来清
 *    实例级缓存，而产物内部有自己的模块实例，清不到 —— 那些用例请跑源码目录。
 */

const path = require('path');
const fs = require('fs');

const ROOT = path.resolve(__dirname, '..', '..');
const BUNDLE_DIR = path.join(ROOT, 'miniprogram', 'cloudfunctions', 'api');

// ⚠️ 必须在 require('./harness') 之前设置
process.env.HARNESS_API_DIR = BUNDLE_DIR;

const H = require('./harness');

const lines = [];
let failed = 0;
function eq(name, got, want) {
  const ok = got === want;
  if (!ok) failed++;
  lines.push(`${ok ? 'OK  ' : 'FAIL'} ${name} :: got=${JSON.stringify(got)} want=${JSON.stringify(want)}`);
}

const bundleFile = path.join(BUNDLE_DIR, 'index.js');

(async () => {
  // 0. 产物本身
  if (!fs.existsSync(bundleFile)) {
    console.log('FAIL 产物不存在，请先跑：node cloud/scripts/sync.js');
    process.exit(1);
  }
  const txt = fs.readFileSync(bundleFile, 'utf8');
  const sizeKb = (txt.length / 1024).toFixed(1);
  lines.push(`INFO 产物：miniprogram/cloudfunctions/api/index.js（${sizeKb} KB）`);
  eq('产物是自动生成的（带 banner）', txt.indexOf('AUTO-GENERATED by cloud/scripts/sync.js') >= 0, true);
  eq('产物是单文件（无 lib/services 子目录依赖）', fs.existsSync(path.join(BUNDLE_DIR, 'lib')), false);
  // ⚠️ 阶段 6 起产物目录多了 config.json（定时触发器配置）。
  //    它必须随 index.js 一起进产物根目录 —— 漏传的表现是「部署成功、定时任务从来不跑」。
  eq('产物文件完整，额外目录仅允许已安装的依赖',
    fs.readdirSync(BUNDLE_DIR).filter((name) => name !== 'node_modules').sort().join(','),
    'config.json,index.js,package-lock.json,package.json');
  eq('产物依赖锁与源文件一致', fs.readFileSync(path.join(BUNDLE_DIR, 'package-lock.json'), 'utf8') ===
    fs.readFileSync(path.join(ROOT, 'cloud', 'cloudfunctions', 'api', 'package-lock.json'), 'utf8'), true);

  // 1. 能启动 + 基本接口可用
  H.reset({});
  const h = await H.call(H.req('GET', '/health'));
  eq('health code（产物可正常启动）', h.code, 0);
  eq('health dbReady', h.data.dbReady, true);
  eq('health jwtReady（外部依赖 jsonwebtoken 走原生 require）', h.data.jwtReady, true);

  const init = await H.call(H.req('POST', '/system/init-collections'));
  eq('init-collections code', init.code, 0);
  eq('init-collections 全部 created', init.data.summary.created, init.data.total);

  // 2. 抽两条不同子目录的 handler，确认都被打进产物了
  const sw = await H.call(H.req('GET', '/user/switch/list'));
  eq('handlers/user/switch.js 已打进产物', sw.code, 0);

  const nl = await H.call(H.req('GET', '/user/notice/list'));
  eq('handlers/user/notice.js 已打进产物', nl.code, 0);
  eq('分页返回结构正确', Array.isArray(nl.data.list) && nl.data.total === 0, true);

  const pr = await H.call(H.req('GET', '/user/program/current'));
  eq('handlers/user/program.js 已打进产物（空库 data=null）', pr.code === 0 && pr.data === null, true);

  const st = await H.call(H.req('GET', '/user/station/intro'));
  eq('services/kv.js 已打进产物（未配置 → 40401）', st.code, 40401);

  const c = await H.call(H.req('GET', '/user/cadre/abc'));
  eq('handlers/user/cadre.js 已打进产物（非法 id → 40401）', c.code, 40401);

  const lg = await H.call(H.req('POST', '/user/login/account', { username: '20999999', password: 'x1234567' }));
  eq('handlers/user/auth.js 已打进产物（依赖 bcryptjs，走原生 require）', lg.code, 40101);

  const pf = await H.call(H.req('GET', '/user/profile'));
  eq('handlers/user/profile.js 已打进产物（未登录 → 40101）', pf.code, 40101);

  /**
   * 3. 阶段 7 新增的管理端模块必须**真被打了进去**。
   *
   * ⚠️ 不能拿「某个还没实现的接口」当「未移植」样本 —— 阶段 7 起管理端 93 条已全部落地，
   *    那种样本会随移植进度不断失效（原先用 `/admin/submit/list`，实现后就变成
   *    「未登录 → 40101」，断言静默变成假红）。
   * ⚠️ 也不能 `require(BUNDLE_DIR + '/handlers')` —— 产物是**单文件**，没有 handlers 目录，
   *    且只导出 `main`，拿不到 `resolveHandler`。
   *    所以判据改成**功能级**：模块没打进去 → `resolveHandler` 抛 50001「模块未登记」；
   *    打进去了 → 第一行 `asSuper/asAdmin` 抛 40101。**两者不会混淆**。
   *    （`resolveHandler` 自身的诊断文案契约在 `test-gateway.js` 里对源码目录断言。）
   */
  const noToken = [
    ['GET', '/admin/student/list'],
    ['PUT', '/admin/student/1'],
    ['POST', '/admin/student/import/commit'],
    ['DELETE', '/admin/student/grade/2024'],
    ['GET', '/admin/submit/list'],
    ['GET', '/admin/stats/overview'],
  ];
  let embedded = 0;
  for (const [m, p] of noToken) {
    const rr = await H.call(H.req(m, p));
    if (rr.code === 40101) embedded++;
    else lines.push(`      ↳ ${m} ${p} → ${rr.code} ${rr.message}`);
  }
  eq('阶段 7 的 6 条管理端入口都已打进产物（未登录 → 40101，而非 50001）', embedded, 6);

  // 产物文本层面再确认 services/roster.js 与 handlers/admin/student.js 的内容确实在
  const bundleText = fs.readFileSync(bundleFile, 'utf8');
  eq('产物内含 services/roster.js 的实现（抓「账号 = 年级+班级+序号」注释）',
    bundleText.indexOf('账号 = 年级') >= 0, true);
  eq('产物内含 handlers/admin/student.js 的实现（抓「学生账号」标签）',
    bundleText.indexOf('学生账号') >= 0, true);
  eq('产物内含 handlers/admin/submit.js 的实现（抓 purgeSongs 的 confirm 文案）',
    bundleText.indexOf('高危操作：请传 confirm') >= 0, true);
  eq('产物内已登记 admin.student 模块', bundleText.indexOf('admin.student') >= 0, true);
  eq('产物内已登记 admin.submit 模块', bundleText.indexOf('admin.submit') >= 0, true);

  lines.push('');
  lines.push(`结论：${lines.length} 行 / 失败 ${failed} 项`);
  console.log(lines.join('\n'));
  process.exit(failed === 0 ? 0 : 1);
})();
